head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > checkboxLabelDelimiter]<br/>checkboxLabelColumn 속성으로 라벨 텍스트를 조합할때 적용할 구분자를 설정합니다.",
    "validation" : [
        "Column 의 inputType='checkbox' 이고 checkboxLabelColumn 속성이 설정된 경우 동작합니다.",
        "구분자 설정 시, 체크박스의 라벨 텍스트를 조합할때 사용할 구분자를 설정합니다.",
        "속성값을 설정하지 않으면 공백(' ')이 구분자로 설정됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    //  - 전제 조건(inputType, checkboxLabelColumn)은 충족값, 검증 대상 속성은 의미 있는 값으로 초기 선택
    con_inputType.setValue("checkbox");
    con_checkboxLabelColumn.setValue("name,price");
    con_checkboxLabelDelimiter.setValue("/");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - Body 의 chk Column 에만 con 값 적용 (inputType / checkboxLabelColumn 은 전제 조건으로만 사용)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cInputType = con_inputType.getValue();
    let cLabelColumn = con_checkboxLabelColumn.getValue();
    let cDelimiter = con_checkboxLabelDelimiter.getValue();

    let attrChk = '';
    attrChk += ' inputType="' + cInputType + '"';
    attrChk += (cLabelColumn === '') ? '' : ' checkboxLabelColumn="' + cLabelColumn + '"';
    attrChk += (cDelimiter === '') ? '' : ' checkboxLabelDelimiter="' + cDelimiter + '"';

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="price" name="price" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "노트북", "price" : "1,250,000", "chk" : "0" },
        { "name" : "모니터", "price" : "320,000", "chk" : "1" },
        { "name" : "키보드", "price" : "89,000", "chk" : "0" },
        { "name" : "마우스", "price" : "45,000", "chk" : "1" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:560px;height:170px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="상품명"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="가격"></w2:column>';
    strTarget += '<w2:column width="300" style="" inputType="text" id="column3" value="선택"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="price" value=""></w2:column>';
    strTarget += '<w2:column width="300" style="text-align:left;" id="chk" value=""' + attrChk + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // validation 1 ~ 3 : 재생성 직후 각 행 라벨 텍스트 출력 (따옴표로 감싸 공백 구분자 확인)
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("라벨 텍스트 : " + scwin.getAllLabelStr());
    }, 100);
}



// Body chk Column 의 행별 라벨 textContent
scwin.getLabelStr = function (rowIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_2']");
    let label = td ? td.querySelector("label") : null;
    return label ? "'" + label.textContent + "'" : "라벨 없음";
}



scwin.getAllLabelStr = function () {
    let arr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        arr.push(i + "행=" + scwin.getLabelStr(i));
    }
    return arr.join(" / ");
}
